begin read only;
select jsonb_build_object('type','inventory','schema',n.nspname,'tables',count(*),'withoutRLS',count(*) filter(where not c.relrowsecurity)) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and c.relkind='r' group by n.nspname;
select jsonb_build_object('type','public_table_without_rls','table',c.relname,'anon_any',has_table_privilege('anon',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE'),'authenticated_any',has_table_privilege('authenticated',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and not c.relrowsecurity;
select jsonb_build_object('type','service_direct_table_grant','object',n.nspname||'.'||c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and c.relkind in ('r','v','m') and has_table_privilege('service_role',c.oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE');
select jsonb_build_object('type','definer_without_pinned_path','function',p.oid::regprocedure::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.prosecdef and not exists(select 1 from unnest(p.proconfig) c where c like 'search_path=%');
select jsonb_build_object('type','anonymous_nonextension_rpc','function',p.oid::regprocedure::text) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prokind='f' and has_function_privilege('anon',p.oid,'execute') and not exists(select 1 from pg_depend d where d.classid='pg_proc'::regclass and d.objid=p.oid and d.deptype='e') order by p.oid::regprocedure::text;
select jsonb_build_object('type','migration_count','count',count(*)) from supabase_migrations.schema_migrations;
select jsonb_build_object('type','storage_bucket','id',id,'public',public,'file_size_limit',file_size_limit,'mime_types',allowed_mime_types) from storage.buckets;
select jsonb_build_object('type','final_hypothesis_predicates','consent_unbounded_history',p.prosrc like '%e.action=''ent.consent_cancel'' and dl.product_id=l.product_id%') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='audited_legacy_supply_command';
select jsonb_build_object('type','final_hypothesis_predicates','lifecycle_cancel_continue',p.prosrc like '%if d.status=''cancelled'' then continue;end if;%','batch25',p.prosrc like '%limit 25%') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='v4_lifecycle_schedule';
rollback;
